/* Blindspot workbench. Local API executes; hosted mode explicitly replays verified fixtures. */
'use strict';
const $ = s => document.querySelector(s);
const escapeHtml = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  layers:'<path d="m3 7 9-5 9 5-9 5-9-5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',
  file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',
  cloud:'<path d="M7 18a5 5 0 1 1 1-10 7 7 0 0 1 13 4 4 4 0 0 1-1 8H7"/>',
  shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z"/><path d="m8 12 3 3 5-6"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 17h.01"/>',
  github:'<path d="M9 19c-5 2-5-2-7-2m14 5v-4a3 3 0 0 0-1-2c3 0 6-2 6-6a5 5 0 0 0-1-4 5 5 0 0 0 0-4s-2 0-4 2a14 14 0 0 0-8 0C6 2 4 2 4 2a5 5 0 0 0 0 4 5 5 0 0 0-1 4c0 4 3 6 6 6a3 3 0 0 0-1 2v4"/>',
  check:'<path d="m5 12 4 4L20 5"/>',
  user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',
  key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-4-4 3-3m-6 0 3-3"/>',
  folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
  message:'<path d="M21 14a3 3 0 0 1-3 3H8l-5 4V5a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3Z"/><path d="M7 7h10M7 11h6"/>',
  lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 15v3"/>',
  image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',
  play:'<path d="m8 4 12 8-12 8Z"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  circle:'<circle cx="12" cy="12" r="9"/><path d="M12 8v5M12 16h.01"/>',
  spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',
  terminal:'<rect x="2" y="3" width="20" height="18" rx="3"/><path d="m6 8 4 4-4 4M13 16h5"/>',
  refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.circle}</svg>`;
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>{e.innerHTML=icon(e.dataset.icon);});}
const cases = {
  'public-storage':{title:'Cloud exposure',subtitle:'A private bucket goes public',icon:'cloud',number:'001',heading:'One small flag.<br>A very public problem.',description:'A storage change opens private documents and credential objects to unauthenticated readers.',ticket:'“An unauthenticated browser can open our customer documents. Was the bucket configuration changed?”',actor:'Anonymous visitor',control:'Storage policy',boundary:'private objects require authorized identities'},
  'privilege-escalation':{title:'Privilege escalation',subtitle:'A member becomes an admin',icon:'key',number:'002',heading:'A normal member.<br>Extraordinary permissions.',description:'A role-management change accepts self-assigned roles and trusts historical administrator claims.',ticket:'“I signed in as a normal member, changed my role, and could perform an administrator action.”',actor:'Standard member',control:'Role assignment',boundary:'only current administrators may assign roles'},
  'revoked-access':{title:'Revoked access',subtitle:'An old session still works',icon:'user',number:'003',heading:'The employee left.<br>Their access didn’t.',description:'An authentication optimization skips the current directory check. A disabled identity keeps reading private documents.',ticket:'“We offboarded this employee, but their existing session can still access private files.”',actor:'Former employee',control:'Active check',boundary:'disabled identities have no access'},
  'clean':{title:'Clean control',number:'004',heading:'Secure access.<br>Working as intended.',description:'The known-good configuration rejects unauthorized requests while keeping legitimate operations available.',ticket:'“Can we demonstrate that valid members and administrators still have the access they need?”',actor:'Active member',control:'Current directory',boundary:'legitimate access must keep working'},
  'combined':{title:'Combined change',number:'005',heading:'Three regressions.<br>One independent contract.',description:'A single change combines public storage, role escalation, and access retained by a disabled employee.',ticket:'“A release changed storage and authentication settings. Which boundaries did it break?”',actor:'Mixed identities',control:'Access policy',boundary:'all three security boundaries remain intact'},
};
let selected='revoked-access', fixtures, report=null, mode='verified-replay', status={}, busy=false, screenshot=null;
const labels={read_document:'Read document',read_credential:'Read credential object',administer:'Administrator operation',assign_admin:'Assign admin → exercise access'};
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>{$('#toast').hidden=true;},3500);}
function modal(title,body){$('#modal-eyebrow').textContent=title;$('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();}
function selectCase(name){if(busy)return;selected=name;report=null;screenshot=null;$('#image-preview').hidden=true;$('#remove-image').hidden=true;$('#screenshot-input').value='';const c=cases[name];$('#case-number').textContent='CASE '+c.number;$('#case-title').innerHTML=c.heading;$('#case-description').textContent=c.description;$('#ticket-text').textContent=c.ticket;$('#path-actor').textContent=c.actor;$('#path-control').textContent=c.control;$('#boundary-text').textContent=c.boundary;$('#status-message').textContent='';$('#run-label').textContent='Run verification';$('#evidence-count').textContent='—';$('#download-button').disabled=true;$('#repair-area').hidden=true;document.querySelectorAll('.scenario-card').forEach(b=>{b.classList.toggle('selected',b.dataset.case===name);b.setAttribute('aria-pressed',b.dataset.case===name);});showTab('changes');resetBanner();renderDiff();renderArtifacts();renderProbes();}
function showTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',active);});document.querySelectorAll('.tab-view').forEach(v=>v.hidden=v.id!=='view-'+tab);}
function resetBanner(){$('#result-banner').className='result-banner pending';$('#result-banner').innerHTML=`<span>${icon('circle')}</span><div><strong>Awaiting verification</strong><small>Inspect the proposed change, then run the frozen checks.</small></div><span class="verdict-pill">NOT RUN</span>`;}
function activeObservations(){return report?.repaired_observations ?? report?.observations ?? [];}
function repairedCandidate(){const candidate=structuredClone(fixtures.scenarios[selected].candidate);for(const op of report?.repair_operations||[]){const segments=op.pointer.slice(1).split('/');let obj=candidate[op.file];for(const key of segments.slice(0,-1))obj=obj[key];obj[segments.at(-1)]=op.value;}return candidate;}
function renderDiff(){if(!fixtures)return;const entry=fixtures.scenarios[selected];let original=entry.baseline,candidate=entry.candidate;if(report?.repair_operations?.length){original=entry.candidate;candidate=repairedCandidate();}const changed=Object.keys(candidate).filter(n=>JSON.stringify(original[n])!==JSON.stringify(candidate[n]));const file=changed[0]||'service/access.json';$('#diff-file').textContent=file+(changed.length>1?` + ${changed.length-1} artifact`:'');let html='',adds=0,removes=0;for(const name of changed.length?changed:[file]){const a=JSON.stringify(original[name],null,2).split('\n'),b=JSON.stringify(candidate[name],null,2).split('\n');if(changed.length>1)html+=`<div class="code-line"><span class="line-number">·</span><span class="code-sign"></span><span class="code-text">// ${escapeHtml(name)}</span></div>`;for(let i=0;i<Math.max(a.length,b.length);i++){const line=(text,kind,sign)=>`<div class="code-line ${kind}"><span class="line-number">${i+1}</span><span class="code-sign">${sign}</span><span class="code-text">${escapeHtml(text)}</span></div>`;if(a[i]===b[i])html+=line(a[i]??'','',' ');else{if(a[i]!==undefined){html+=line(a[i],'removed','−');removes++;}if(b[i]!==undefined){html+=line(b[i],'added','+');adds++;}}}}$('#diff-editor').innerHTML=html;$('#diff-stats').textContent=adds||removes?`+${adds}  −${removes}`:'No changes';}
function renderArtifacts(){if(!fixtures)return;const candidate=report?.repair_operations?.length?repairedCandidate():fixtures.scenarios[selected].candidate;$('#artifact-list').innerHTML=Object.entries(candidate).map(([name,value])=>`<details class="artifact"><summary>${escapeHtml(name)}</summary><pre>${escapeHtml(JSON.stringify(value,null,2))}</pre></details>`).join('');$('#fingerprint').textContent=report?'Frozen contract SHA-256 · '+report.contract_hash:'Requirements and identities remain independent of candidate settings.';}
function renderProbes(){const rows=activeObservations();if(!report){$('#probe-list').innerHTML=`<div class="empty-state"><span>${icon('terminal')}</span><strong>Let the checks speak.</strong><p>Every finding will include the request,<br>expected outcome, and actual decision trace.</p></div>`;$('#probe-summary').textContent='Run verification to collect evidence.';return;}const failed=rows.filter(o=>!o.passed).length;$('#probe-summary').textContent=`${rows.length} executed checks · ${failed} failed`;const filtered=$('#failures-only').checked?rows.filter(o=>!o.passed):rows;$('#probe-list').innerHTML=filtered.map(o=>`<details class="probe-row ${o.passed?'':'failed'}"><summary><span class="probe-result">${o.passed?'PASS':'FAIL'}</span><div>${escapeHtml(labels[o.probe.action]||o.probe.action)}<small>${escapeHtml(o.probe.actor)} → ${escapeHtml(o.probe.resource)}</small></div></summary><div class="probe-trace">Expected ${o.probe.expected_allowed?'ALLOW':'DENY'} · observed ${o.allowed?'ALLOW':'DENY'}\n\n${escapeHtml(o.trace.join('\n'))}</div></details>`).join('')||'<div class="empty-state"><strong>No failing checks.</strong><p>All required access boundaries held.</p></div>';}
function renderResult(){const verdict=report.final_verdict,rows=activeObservations(),failed=rows.filter(o=>!o.passed).length;const controls=rows.filter(o=>o.passed&&o.probe.expected_allowed).length;const repaired=!!report.repair_verdict;$('#result-banner').className='result-banner '+(verdict==='PASS'?'passed':verdict==='BLOCK'?'blocked':'pending');$('#result-banner').innerHTML=`<span>${icon(verdict==='PASS'?'check':'shield')}</span><div><strong>${verdict==='PASS'?(repaired?'Repair verified. The boundary holds.':'The access contract holds.'):verdict==='BLOCK'?'Access boundary broken. Change blocked.':'Verification needs attention.'}</strong><small>${failed} failing checks · ${controls} legitimate-access controls passed${mode==='verified-replay'?' · recorded execution':''}</small></div><span class="verdict-pill">${escapeHtml(verdict)}</span>`;$('#evidence-count').textContent=rows.length;$('#download-button').disabled=false;$('#repair-area').hidden=verdict==='PASS';$('#repair-title').textContent=verdict==='INCONCLUSIVE'?'No approval issued.':'A failure is only the beginning.';$('#repair-description').textContent=verdict==='INCONCLUSIVE'?'Inspect the evidence ledger for the error, then retry.':'Propose a minimal repair and run the same checks again.';$('#run-label').textContent='Replay verification';$('#status-message').textContent=report.notes.filter(n=>/unavailable|rejected|invalid/i.test(n)).join(' ');renderDiff();renderArtifacts();renderProbes();}
async function verify(repair=false){if(busy||!fixtures)return;busy=true;document.body.classList.add('busy');$('#run-button').disabled=true;$('#repair-button').disabled=true;$('#status-message').textContent=mode==='local'?'Executing the frozen policy checks…':'Loading recorded Python execution evidence…';try{if(mode==='local'){const models=$('#models-toggle').checked;const response=await fetch('/api/security',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:selected,repair,models,images:models&&screenshot?[screenshot]:[]})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Verification failed');report=result;}else{report=structuredClone(fixtures.scenarios[selected][repair?'repair':'before']);}$('#status-message').textContent='';renderResult();if(repair&&report.final_verdict==='PASS')toast('Repair verified against the same frozen checks.');}catch(error){$('#status-message').textContent=error.message;toast('No approval issued. Inspect the error and try again.');}finally{busy=false;document.body.classList.remove('busy');$('#run-button').disabled=false;$('#repair-button').disabled=false;}}
function openGuide(){modal('THE WORKFLOW',`<h2>See the risk.<br>Prove the fix.</h2><p>Choose a security scenario and inspect the proposed configuration. Run verification to execute the independent access contract. Open the evidence ledger for every request and decision trace.</p><p><strong>Verify a repair</strong> proposes configuration replacements, then reruns the identical checks. A repair cannot change the requirements or test identities. Denying every request fails the legitimate-access controls.</p><pre>cd /Users/dhruvmiyani/new-hack\n.venv/bin/python serve.py</pre><p>Local workbench: <a href="http://127.0.0.1:8765" target="_blank" rel="noreferrer">http://127.0.0.1:8765 ↗</a></p><p>The hosted sandbox replays recorded execution. Local mode runs the Python harness afresh. Both use fictional data; neither changes cloud resources.</p>`);}
function openModels(){modal('MODEL CONNECTIONS',`<h2>Two models.<br>One evidence standard.</h2><p><strong>SubQ Snap</strong> receives complete policy, identity, session, and configuration artifacts to select the risk surface. An optional screenshot adds visual evidence; its judgment remains advisory.</p><p><strong>Meta Muse</strong> proposes a restricted JSON configuration repair. The executed checks determine whether it passes.</p><pre>SUBQ_API_KEY=…\nMETA_API_KEY=…\n\n.venv/bin/python serve.py</pre><p>Keep keys in the local <code>.env</code> file. The browser and hosted sandbox never receive them. Restart the local server after configuring keys.</p><p>Current connection: ${mode==='local'?`Meta ${status.meta?'configured':'not configured'} · SubQ ${status.subq?'configured':'not configured'}`:'hosted replay; local model calls unavailable'}.</p>`);}
function openScope(){modal('VERIFICATION SCOPE',`<h2>A precise claim.<br>With evidence attached.</h2><p>The sandbox verifies a small object-storage and member/admin permissions model. It covers anonymous reads, credential-object access, self-assigned admin roles, stale role claims, and offboarded identities.</p><p>These are seeded failures in fictional configuration. Passing the 24 checks proves this local contract; it is not a claim about every possible vulnerability or a scan of a cloud account.</p><p>The <strong>Google Cloud</strong> connector performs real read-only inventory and optional canary-file probes through the local Google Cloud CLI. Conditional policies, group membership, and organization inheritance may require further investigation.</p>`);}
function openGCP(){modal('GOOGLE CLOUD · READ ONLY',`<h2>Inspect a real<br>permission boundary.</h2><p>Read bucket and project IAM policies using your local Google Cloud sign-in. Optionally verify that an offboarded test service account cannot read a fictional canary.</p><div class="modal-warning">${mode==='local'?'Read-only: no IAM grants, bucket changes, or credential downloads.':'Live GCP checks require the local workbench. This hosted sandbox cannot access your local Google sign-in.'}</div><form id="gcp-form"><label for="gcp-project">Project ID</label><input id="gcp-project" name="project" placeholder="my-security-sandbox" required pattern="[a-z][a-z0-9-]{4,28}[a-z0-9]"><label for="gcp-bucket">Bucket name</label><input id="gcp-bucket" name="bucket" placeholder="my-private-demo-bucket" required><label for="gcp-actor">Test service account · optional</label><input id="gcp-actor" name="actor" placeholder="offboarded-demo@project.iam.gserviceaccount.com"><label for="gcp-object">Fictional canary object · use with the test identity</label><input id="gcp-object" name="object_name" placeholder="blindspot-canary.txt"><button class="run-button" type="submit" ${mode==='local'?'':'disabled'}>${icon('cloud')} Inspect permissions</button></form><div id="gcp-output" class="gcp-result" aria-live="polite"></div><p>Setup: <code>gcloud auth login</code>. Canary probes also need permission to impersonate the test service account. No permanent service-account keys are used.</p>`);$('#gcp-form').addEventListener('submit',async e=>{e.preventDefault();if(mode!=='local')return;const button=e.target.querySelector('button');button.disabled=true;$('#gcp-output').textContent='Reading Google Cloud policies…';try{const data=Object.fromEntries(new FormData(e.target));const res=await fetch('/api/gcp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await res.json();if(!res.ok)throw new Error(value.error);$('#gcp-output').innerHTML=`<strong>${escapeHtml(value.verdict)} · Read-only evidence</strong><p>${escapeHtml(value.scope)}</p><pre>${escapeHtml(JSON.stringify({findings:value.findings,probe:value.probe,control:value.control,notes:value.notes},null,2))}</pre>`;}catch(error){$('#gcp-output').textContent=error.message;}finally{button.disabled=false;}});}
async function init(){paintIcons();$('#scenario-grid').innerHTML=['public-storage','privilege-escalation','revoked-access'].map(name=>{const c=cases[name];return `<button class="scenario-card" data-case="${name}" aria-pressed="false"><span class="scenario-icon">${icon(c.icon)}</span><div><strong>${c.title}</strong><small>${c.subtitle}</small></div><span class="scenario-radio"></span></button>`;}).join('');document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>selectCase(b.dataset.case)));try{const response=await fetch('/scenarios.json');if(!response.ok)throw new Error('Could not load sandbox evidence');fixtures=await response.json();}catch(error){$('#status-message').textContent=error.message;$('#run-button').disabled=true;return;}try{const response=await fetch('/api/status',{signal:AbortSignal.timeout(2500)});const value=await response.json();if(value.mode==='local'){mode='local';status=value;}}catch{}$('#mode-badge').innerHTML=`<i></i> ${mode==='local'?'Local execution':'Verified replay sandbox'}`;$('#scope-caption').textContent=mode==='local'?'Fresh local execution · no cloud changes':'Recorded Python execution · hosted replay';selectCase(selected);}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));
$('#run-button').addEventListener('click',()=>verify(false));$('#repair-button').addEventListener('click',()=>verify(true));$('#failures-only').addEventListener('change',renderProbes);
$('#clean-control').addEventListener('click',()=>selectCase('clean'));$('#workbench-nav').addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));$('#ledger-nav').addEventListener('click',()=>{showTab('evidence');$('#evidence-panel').scrollIntoView({behavior:'smooth',block:'center'});});$('#help-button').addEventListener('click',openGuide);$('#scope-button').addEventListener('click',openScope);$('#model-info').addEventListener('click',openModels);$('#gcp-nav').addEventListener('click',openGCP);$('#close-modal').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
$('#models-toggle').addEventListener('change',e=>{if(e.target.checked&&(mode!=='local'||!status.meta||!status.subq)){e.target.checked=false;openModels();}});
$('#attach-button').addEventListener('click',()=>{if(mode!=='local'||!$('#models-toggle').checked){openModels();return;}$('#screenshot-input').click();});
$('#screenshot-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){toast('Choose a PNG, JPEG, or WebP screenshot under 2 MiB.');return;}const reader=new FileReader();reader.onload=()=>{const value=String(reader.result);screenshot={mediaType:file.type,base64:value.split(',')[1]};const image=document.createElement('img');image.src=value;image.alt='Console screenshot attached as supporting evidence';$('#image-preview').replaceChildren(image);$('#image-preview').hidden=false;$('#remove-image').hidden=false;};reader.readAsDataURL(file);});
$('#remove-image').addEventListener('click',()=>{screenshot=null;$('#image-preview').hidden=true;$('#remove-image').hidden=true;$('#screenshot-input').value='';});
$('#download-button').addEventListener('click',()=>{if(!report)return;const blob=new Blob([JSON.stringify({...report,presentation_mode:mode},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`blindspot-${selected}-evidence.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&!$('#modal').open){e.preventDefault();verify(false);}});
init();
